{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C42"],
      "claim": "Cilomilast absolute oral bioavailability is 96% (range 92–102%) in healthy volunteers after oral solution vs IV infusion, demonstrating that a small lipophilic oral drug can be essentially completely absorbed; high transfer supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Nevirapine absolute oral bioavailability is 91 ± 8% in healthy volunteers (oral solution vs IV), showing high oral absorption for a lipophilic small-molecule drug; high transfer supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Ethosuximide, a small low-molecular-weight drug, has oral bioavailability >90% in humans, supporting that small, rigid, non-acidic molecules can be completely absorbed; high transfer supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Rasagiline, a small lipophilic basic amine CNS drug, has absolute oral bioavailability ~36% in humans, above the 20% threshold; despite first-pass metabolism, the basic amine feature does not preclude F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Bicifadine, a basic amine analgesic, has absolute oral bioavailability ~67% in humans, supporting that basic amine drugs can achieve high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Pentazocine, a basic amine with a phenolic group, has low oral bioavailability ~18% in healthy subjects, but this is attributed to extensive first-pass metabolism/phenol conjugation; the query lacks these metabolic soft spots, so this low-F evidence is not directly transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a small, rigid adamantane primary amine (memantine-like). Multiple high-transfer human absolute bioavailability measurements for small lipophilic drugs, including basic amines, show F values well above 20% (cilomilast 96%, nevirapine 91%, ethosuximide >90%, bicifadine 67%, rasagiline 36%). The only low-F analogue, pentazocine, has a phenolic first-pass liability absent in the query. Physicochemical ionization concerns are outweighed by the consistent experimental evidence for high oral absorption in this chemical space. Prediction: high.",
  "evidence_gaps": [
    "No direct experimental absolute oral bioavailability measurement for the query molecule itself.",
    "No memantine/amantadine-specific analogue record in the provided evidence; transfer relies on structurally related small basic amines.",
    "Metabolic first-pass extent for the query is not directly measured; however its rigid adamantane core and primary amine are expected to limit the phenolic/glucuronidation liability seen in pentazocine."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

